TAB_StrongerIntroduction = TAB_StrongerIntroduction or {}
TAB_StrongerIntroduction[-1] = {"s_Name","u_Des"}
TAB_StrongerIntroduction[1] = {"Làm sao chọn anh hùng ra trận",{{"      #C(#FF9900)→Chú ý phối hợp Nghề:"},{"#C(#7f5f43) 1 đội hình hoàn chỉnh thường do 3 bộ phận tạo thành #C(#459921)Anh hùng Tank#C(#7f5f43) (Phụ trách khống chế bảo vệ), #C(#459921)Chiến Binh, Anh hùng Pháp Sư#C(#7f5f43) (Phụ trách tạo sát thương), #C(#459921)Anh hùng Hỗ Trợ#C(#7f5f43) (Phụ trách Buff trị liệu)"},{"      #C(#FF9900)→Chú ý khắc chế đội hình:"},{"#C(#7f5f43) hiệu quả khắc chế đội hình mang lại tăng sát thương khách quan trong chiến đấu, dựa theo đội hình phe địch lựa chọn đội hình khắc chế hợp lý cũng là yếu tố quyết định thắng lợi"},{"      #C(#FF9900)→Chú ý phối hợp đội hình:"},{"#C(#7f5f43) anh hùng đội hình chỉ định ra trận có thể nhận được tăng thuộc tính trong chiến đấu, dựa theo đội hình phối hợp hợp lý của anh hùng mà bản thân có cũng có thể tăng cao xác suất chiến thắng"},{"      #C(#FF9900)→Chú ý tổ hợp kỹ năng:"},{"#C(#7f5f43) đa số các kỹ năng của anh hùng có thể phối hợp lẫn nhau"},{"      #C(#FF9900)→chú ý số lượng anh hùng:"},{"#C(#7f5f43) trong lối chơi của chương Cốt Truyện mới, 3 anh hùng cùng tên không thể đồng thời ra trận"}}}
TAB_StrongerIntroduction[2] = {"Làm sao chọn chiến thuật",{{"      #C(#FF9900)→Dựa theo nghề của anh hùng phe ta:"},{"#C(#7f5f43) có thể dựa theo nghề của anh hùng ra trận thực tế để quyết định, ví dụ ra trận là #C(#459921)2 anh hùng loại Khiên Thịt#C(#7f5f43), đề xuất dùng #C(#459921)Trận Thần Đạo#C(#7f5f43), từ đó tăng mạnh bảo hộ anh hùng khác của phe ta"},{"      #C(#FF9900)→Dựa theo đội hình của đối thủ:"},{"#C(#7f5f43) có thể dựa theo anh hùng ra trận của đối thủ để quyết định, đối với những sát thương AOE đặc biệt, thông qua #C(#459921)điều chỉnh vị trí đứng#C(#7f5f43) để tránh loại kỹ năng khống chế này"},{"      #C(#FF9900)→Đổi chiến thuật:"},{"#C(#7f5f43) nếu gặp phải trận chiến không thể thắng được, điều chỉnh chiến thuật rồi đánh lại có thể có hiệu quả"}}}
TAB_StrongerIntroduction[3] = {"Làm sao thức tỉnh anh hùng",{{"      #C(#FF9900)→Lợi ích của Thức Tỉnh:"},{"#C(#7f5f43) Thức Tỉnh có thể tăng mạnh thuộc tính của anh hùng, đồng thời Thức Tỉnh cũng là cách duy nhất tăng cấp kỹ năng của anh hùng"},{"        #C(#FF9900)→Cách Thức Tỉnh:"},{"#C(#7f5f43) đến #C(#459921)Phòng Nghiên Cứu#C(#7f5f43) trong giao diện Thành Chính, chọn anh hùng mà bạn muốn Thức Tỉnh, dựa theo nhắc nhở thêm các anh hùng khác vào là có thể Thức Tỉnh, anh hùng 6 sao có thể trực tiếp thực hiện thao tác Thức Tỉnh trong giao diện Dưỡng Anh Hùng"},{"      #C(#FF9900)→Hiển thị tình bạn:"},{"#C(#7f5f43) vì 1 luồng sức mạnh thần bí, nên không phải tất cả các anh hùng đều có thể tăng lên cấp sao tối đa, khi Dưỡng Anh Hùng cần phải chú ý"}}}
TAB_StrongerIntroduction[4] = {"Làm sao để đồng đội trưởng thành nhanh chóng?",{{"  #C(#459921)→#C(#7f5f43)Mỗi ngày miễn phí #C(#459921)Triệu Hồi, Đổi Vàng và tác chiến nhanh#C(#7f5f43) đừng bỏ lỡ"}, {"  #C(#459921)→#C(#7f5f43)mỗi ngày có thể khiêu chiến Phụ Bản Ngày trong #C(#459921)Lịch Luyện#C(#7f5f43), tham gia các lối chơi có thể nhận các lợi ích"}, {"  #C(#459921)→#C(#7f5f43)mỗi ngày nhấn Like cho người chơi trong BXH của Đấu Trường cũng có hể nhận Vàng"}, {"  #C(#459921)→#C(#7f5f43)gia nhập Guild, tiêu hao Cống Hiến học kỹ năng Guild cũng có thể giúp anh hùng nhận được tăng cực đại"},{"  #C(#459921)→#C(#7f5f43)Quan trọng nhất-#C(#459921)lợi ích treo máy#C(#7f5f43) đừng quên online mỗi ngày để nhận"}}}
TAB_StrongerIntroduction[5] = {"Làm sao tăng cấp nhân vật nhanh?",{{"      #C(#459921)Nhận EXP nhân vật:"},{"#C(#7f5f43) chiến đấu Cốt Truyện, treo máy Cốt Truyện và tác chiến nhanh là cách duy nhất nhận được EXP nhân vật, số ải đạt được càng cao, EXP nhân vật nhận được khi treo máy càng nhiều"},{"      #C(#459921) liên quan đến tác chiến nhanh:"},{"#C(#7f5f43) tác chiến nhanh có thể #C(#459921)trực tiếp nhận lợi ích treo máy 120 phút#C(#7f5f43), là con đường tắt để nhận EXP nhân vật"},{"      #C(#459921) đặc biệt chú ý:"},{"#C(#7f5f43) cấp vip càng cao, mỗi lần treo máy nhận được lợi ích khác nhau càng cao, sau khi mua #C(#459921)Đặc quyền tác chiến nhanh#C(#7f5f43) mỗi ngày có thể nhận 3 lượt tác chiến nhanh miễn phí, còn có thể mua thêm 11 lần tác chiến nhanh, những Bậc Thầy Khế Ước muốn tăng cấp nhanh đừng nên bỏ lỡ"}}}
TAB_StrongerIntroduction[6] = {"Làm sao dùng Kim Cương để đạt được hiệu quả cao nhất?",{{"      #C(#459921)Tác chiến nhanh:"},{"#C(#7f5f43) mỗi lần tác chiến nhanh đều có thể trực tiếp nhận lợi ích treo máy 120 phút, đề xuất mua hết mỗi ngày"},{"      #C(#459921) Phụ bản mỗi ngày:"},{"#C(#7f5f43) dùng Kim Cương mua lượt phụ bản mỗi ngày cũng rất có lợi"},{"      #C(#459921) nhiệm vụ Lịch Luyện:"},{"#C(#7f5f43) nếu gặp phải nhiệm vụ Lịch Luyện không muốn làm, có thể dùng Kim Cương để làm mới, có thể có thưởng tốt hơn"},{"      #C(#459921) Phụ bản Guild:"},{"#C(#7f5f43) mua lượt để tăng tốc tiến độ phụ bản, từ đó nhanh chóng nhận Cống Hiến Guild, ngoài ra xếp hạng sát thương càng cao, Cống Hiến Guild nhận được cũng càng nhiều"},{"      #C(#459921) đặc biệt chú ý:"},{"#C(#7f5f43) phải mua Quà Lịch Luyện của Shop Đặc Quyền, sau khi đạt VIP2, mỗi ngày có thể mua 1 Vé Triệu Hồi Cao Cấp giá trị"}}}
TAB_StrongerIntroduction[7] = {"Hiệu quả các kỹ năng anh hùng có tác dụng gì?",{{"#C(#7f5f43)1. Thiêu đốt, Mất HP, Lời nguyền, Trúng độc"},{"#C(#7f5f43) mỗi lượt chịu sát thương cố định, số tầng cộng dồn càng nhiều, sát thương càng cao"},{"#C(#7f5f43)2. Choáng, Hóa đá, Đóng băng, Ngủ, Tê liệt"},{"#C(#7f5f43) anh hùng không thể hành động"},{"#C(#7f5f43)3. Phong ấn"},{"#C(#7f5f43) đơn vị mang trạng thái này không thể gây ra bạo kích, không thể phát động kỹ năng bị động"},{"#C(#7f5f43)4. Yếu ớt"},{"#C(#7f5f43) đơn vị mang trạng thái này không thể sử dụng kỹ năng"},{"#C(#7f5f43)6. Khiêu khích"},{"#C(#7f5f43) đơn vị mang trạng thái này sẽ cưỡng chế chỉ sử dụng đánh thường tấn công người khiêu khích"},{"#C(#7f5f43)7. Quy tắc cộng dồn Buff"},{"#C(#7f5f43) Buff cùng loại mặc định không cộng dồn, Buff có thể cộng dồn sẽ được hướng dẫn đặc biệt trong phần miêu tả Buff"},{"#C(#7f5f43) khi một vài Buff cùng tồn tại với Buff cùng loại khác, chỉ có 1 Buff mạnh nhất có hiệu lực (Ví dụ Phá giáp), và trong phần xem trước chỉ hiển thị 1 tầng trong đó (Vì thế khi 1 tầng của loại Buff này trên thân anh hùng bị {Thanh tẩy} hoặc {Dịch chuyển tai họa}, vẫn sẽ hiển thị 1 tầng"}}}
TAB_StrongerIntroduction[8] = {"Thứ tự ra tay của anh hùng trong chiến đấu như thế nào?",{{"      #C(#FF9900)→Thứ tự ra tay:"},{"#C(#7f5f43) khi mỗi lượt bắt đầu, dựa theo #C(#459921)tốc độ cao thấp#C(#7f5f43) của đơn vị trong trận chiến, quyết định thứ tự ra tay trong lượt này, trong quá trình nếu thay đổi tốc độ, sẽ ảnh hưởng thứ tự ra tay khi bắt đầu lượt tiếp theo"}}}
